#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <stdexcept>

constexpr char numero = 'n';
constexpr char nombre = 'v';
constexpr char declaracion = 'd';
constexpr char constante = 'c';
constexpr char final_texto = 'f';

struct Token {
    char clase;
    int valor;
    std::string texto;
};

bool es_letra(char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
}

bool es_digito(char c) {
    return c >= '0' && c <= '9';
}

bool sigue_nombre(char c) {
    return es_letra(c) || es_digito(c) || c == '_';
}

bool nombre_valido(const std::string& texto) {
    if (texto.empty() || texto.size() > 12 || !es_letra(texto[0])) {
        return false;
    }
    for (char c : texto) {
        if (!sigue_nombre(c)) return false;
    }
    return texto != "crea" && texto != "fija";
}

Token palabra_token(const std::string& palabra) {
    if (palabra == "crea") return Token{declaracion, 0, ""};
    if (palabra == "fija") return Token{constante, 0, ""};
    return Token{nombre, 0, palabra};
}

Token leer_token(std::istringstream& entrada) {
    char actual = '?';
    while (entrada.get(actual)) {
        if (actual == ' ' || actual == '\t' || actual == '\n') continue;
        if (es_digito(actual)) {
            int valor = actual - '0';
            while (entrada.get(actual)) {
                if (es_digito(actual)) {
                    valor = valor * 10 + (actual - '0');
                    if (valor > 99) throw std::runtime_error("Nombre hors domaine");
                } else {
                    entrada.putback(actual);
                    if (!entrada) throw std::runtime_error("Impossible de restituer le caractère");
                    return Token{numero, valor, ""};
                }
            }
            if (entrada.bad() || !entrada.eof()) throw std::runtime_error("Échec du flux");
            return Token{numero, valor, ""};
        }
        if (es_letra(actual)) {
            std::string palabra(1, actual);
            while (entrada.get(actual)) {
                if (sigue_nombre(actual)) {
                    palabra += actual;
                    if (palabra.size() > 12) throw std::runtime_error("Nom trop long");
                } else {
                    entrada.putback(actual);
                    if (!entrada) throw std::runtime_error("Impossible de restituer le caractère");
                    return palabra_token(palabra);
                }
            }
            if (entrada.bad() || !entrada.eof()) throw std::runtime_error("Échec du flux");
            return palabra_token(palabra);
        }
        if (actual == '+' || actual == '-' || actual == '*' || actual == '/'
                || actual == '%' || actual == '(' || actual == ')'
                || actual == ';' || actual == '=') {
            return Token{actual, 0, ""};
        }
        throw std::runtime_error("Caractère non admis");
    }
    if (entrada.bad() || !entrada.eof()) throw std::runtime_error("Échec du flux");
    return Token{final_texto, 0, ""};
}

bool token_valido(const Token& token) {
    if (token.clase == numero) {
        return token.valor >= 0 && token.valor <= 99 && token.texto.empty();
    }
    if (token.clase == nombre) {
        return token.valor == 0 && nombre_valido(token.texto);
    }
    const bool signo = token.clase == '+' || token.clase == '-' || token.clase == '*'
        || token.clase == '/' || token.clase == '%' || token.clase == '('
        || token.clase == ')' || token.clase == ';' || token.clase == '=';
    return token.valor == 0 && token.texto.empty()
        && (signo || token.clase == declaracion || token.clase == constante || token.clase == final_texto);
}

class Lector_tokens {
public:
    explicit Lector_tokens(const std::string& texto) : entrada_{texto} {
        if (texto.size() > 120) throw std::runtime_error("Texte trop long");
    }

    Token leer() {
        if (lleno_) {
            lleno_ = false;
            return guardado_;
        }
        return leer_token(entrada_);
    }

    void devolver(const Token& token) {
        if (lleno_) throw std::runtime_error("Tampon occupé");
        if (!token_valido(token)) throw std::runtime_error("Token invalide");
        guardado_ = token;
        lleno_ = true;
    }

    bool descartar_operacion() {
        if (entrada_.bad()) throw std::runtime_error("Échec grave du flux");
        if (lleno_) {
            const Token pendiente = guardado_;
            lleno_ = false;
            if (pendiente.clase == ';') return true;
            if (pendiente.clase == final_texto) return false;
        }
        entrada_.clear();
        char c = '?';
        while (entrada_.get(c)) {
            if (c == ';') return true;
        }
        if (entrada_.bad() || !entrada_.eof()) throw std::runtime_error("Échec du flux");
        return false;
    }

private:
    std::istringstream entrada_;
    bool lleno_ = false;
    Token guardado_{final_texto, 0, ""};
};

int resultado_en_dominio(int candidato) {
    if (candidato < -100 || candidato > 100) {
        throw std::runtime_error("Résultat hors domaine");
    }
    return candidato;
}

struct Vinculo {
    std::string nombre;
    int valor;
    bool modificable;
};

class Tabla_nombres {
public:
    bool contiene(const std::string& nombre_buscado) const {
        for (const Vinculo& dato : datos_) {
            if (dato.nombre == nombre_buscado) return true;
        }
        return false;
    }

    int consultar(const std::string& nombre_buscado) const {
        for (const Vinculo& dato : datos_) {
            if (dato.nombre == nombre_buscado) return dato.valor;
        }
        throw std::runtime_error("Nom non défini");
    }

    void definir(const std::string& nuevo, int valor, bool modificable) {
        if (!nombre_valido(nuevo)) throw std::runtime_error("Nom invalide");
        resultado_en_dominio(valor);
        if (contiene(nuevo)) throw std::runtime_error("Nom déjà défini");
        if (datos_.size() >= 8) throw std::runtime_error("Table pleine");
        datos_.push_back(Vinculo{nuevo, valor, modificable});
    }

    void asignar(const std::string& existente, int valor) {
        resultado_en_dominio(valor);
        for (Vinculo& dato : datos_) {
            if (dato.nombre == existente) {
                if (!dato.modificable) throw std::runtime_error("Nom constant");
                dato.valor = valor;
                return;
            }
        }
        throw std::runtime_error("Nom non défini");
    }

    const std::vector<Vinculo>& entradas() const {
        return datos_;
    }

private:
    std::vector<Vinculo> datos_;
};

